package com.procats.study;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.*;
import org.robolectric.shadows.ShadowAppWidgetManager;
import android.appwidget.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;
import com.procats.companion.*;import org.json.*;import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w400dp-h900dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class WidgetUiTest {
 Context c;Store s;AppWidgetManager manager;ShadowAppWidgetManager shadow;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("procats_companion_v1",0).edit().clear().commit();s=new Store(c);String scope=s.bind("a".repeat(64));JSONObject data=new JSONObject("{\"schema\":1,\"date\":\""+Model.today()+"\",\"done\":2,\"missed\":0,\"total\":6,\"lang\":\"tr\",\"colors\":{\"accent\":\"#168CFF\",\"background\":\"#202126\",\"text\":\"#F5F5F7\"},\"tasks\":[{\"id\":\"10\",\"identity\":\"a-b\",\"title\":\"Matematik\",\"desc\":\"Problemler · 30 soru\",\"status\":0},{\"id\":\"11\",\"identity\":\"c-d\",\"title\":\"Paragraf\",\"desc\":\"20 soru çöz\",\"status\":0},{\"id\":\"12\",\"identity\":\"e-f\",\"title\":\"Fen tekrarı\",\"status\":0}]}");s.publish(scope,data,new JSONArray());manager=AppWidgetManager.getInstance(c);shadow=Shadows.shadowOf(manager);}
 void prepareDraw(View v){v.forceLayout();v.invalidate();if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)prepareDraw(g.getChildAt(i));}}
 void capture(View v,String name,int width,int height)throws Exception{prepareDraw(v);v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));v.layout(0,0,width,height);Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);v.draw(canvas);int bright=0;for(int yy=0;yy<height;yy++)for(int xx=0;xx<width;xx++){int pixel=b.getPixel(xx,yy);if(Color.alpha(pixel)>240&&Color.red(pixel)>200&&Color.green(pixel)>200&&Color.blue(pixel)>200)bright++;}assertTrue("Rendered widget must contain visible task/action text",bright>100);File dir=new File(System.getProperty("procats.qa.dir","build/previews"));dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void focusWidgetCanInflateAndDisplay()throws Exception{int id=shadow.createWidget(FocusWidget.class,R.layout.widget_focus);View v=shadow.getViewFor(id);assertEquals("Matematik",((TextView)v.findViewById(R.id.widget_title)).getText().toString());capture(v,"widget-focus",440,560);}
 @Test public void wideWidgetDisplaysUpcomingTasks()throws Exception{int id=shadow.createWidget(TodayWidget.class,R.layout.widget_today);View v=shadow.getViewFor(id);assertTrue(((TextView)v.findViewById(R.id.widget_next)).getText().toString().contains("Paragraf"));capture(v,"widget-today",720,600);}
 @Test public void completedTaskAdvancesWithoutCloud()throws Exception{int id=shadow.createWidget(FocusWidget.class,R.layout.widget_focus);s.act("10",1);new FocusWidget().onUpdate(c,manager,new int[]{id});View v=shadow.getViewFor(id);assertEquals("Paragraf",((TextView)v.findViewById(R.id.widget_title)).getText().toString());assertEquals(View.VISIBLE,v.findViewById(R.id.widget_undo).getVisibility());capture(v,"widget-focus-next",440,560);}
 @Test public void logoutClearsHomeScreenCopy()throws Exception{int id=shadow.createWidget(TodayWidget.class,R.layout.widget_today);s.lock();new TodayWidget().onUpdate(c,manager,new int[]{id});View v=shadow.getViewFor(id);assertEquals(View.GONE,v.findViewById(R.id.widget_actions).getVisibility());assertEquals("Telefonda başla",((TextView)v.findViewById(R.id.widget_title)).getText().toString());}
}
